import ast,base64,shutil
from pathlib import Path
from datetime import datetime
PAYLOAD=''

def painel(source):
    tree=ast.parse(source)
    if any(isinstance(n,ast.ImportFrom) and n.module=='layout_0420' for n in tree.body):return source
    if not any(isinstance(n,ast.ClassDef) and n.name=='Window' for n in tree.body):raise RuntimeError('Window não encontrada no módulo atual.')
    index=next((i for i,n in enumerate(tree.body) if isinstance(n,ast.If) and '__name__' in ast.unparse(n.test)),None)
    if index is None:raise RuntimeError('Ponto de inicialização não reconhecido.')
    tree.body[index:index]=ast.parse('from layout_0420 import ativar as _ativar_layout_0420\n_ativar_layout_0420(globals())').body
    ast.fix_missing_locations(tree);return ast.unparse(tree)+'\n'

def instalador(source):
    tree=ast.parse(source);found=False
    for n in ast.walk(tree):
        if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='arquivos' for t in n.targets) and isinstance(n.value,ast.List):
            values=[getattr(v,'value',None) for v in n.value.elts]
            if 'painel_jogadores.py' in values:
                found=True
                if 'layout_0420.py' not in values:n.value.elts.append(ast.Constant(value='layout_0420.py'))
    if not found:raise RuntimeError('Lista de módulos não reconhecida.')
    ast.fix_missing_locations(tree);return ast.unparse(tree)+'\n'

def main():
    root=Path(__file__).resolve().parent;result={}
    for name,adapt in [('painel_jogadores.py',painel),('gerar_instalador.py',instalador)]:
        path=root/name
        if not path.is_file():raise RuntimeError('Arquivo ausente: '+name+'. Coloque o atualizador em GeradorMapaAoE2.')
        result[name]=adapt(path.read_text(encoding='utf-8-sig'))
    result['layout_0420.py']=base64.b64decode(PAYLOAD).decode('utf-8')
    for name,code in result.items():compile(code,name,'exec')
    backup=root/'backups_atualizacoes'/datetime.now().strftime('%Y%m%d-%H%M%S-%f');backup.mkdir(parents=True)
    existed={n:(root/n).is_file() for n in result}
    for n in result:
        if existed[n]:shutil.copy2(root/n,backup/n)
    try:
        for n,code in result.items():
            temp=root/(n+'.tmp');temp.write_text(code,encoding='utf-8');temp.replace(root/n)
    except Exception:
        for n in result:
            if existed[n]:shutil.copy2(backup/n,root/n)
            else:(root/n).unlink(missing_ok=True)
        raise
    print('Layout reorganizado. Backup:',backup)
    print('Se o sistema de patches estiver ativo: py -3.12 gerar_patch.py')
    print('Caso contrário: py -3.12 gerar_atualizacao.py')
    print('Informe uma versão superior à última gerada. Depois aplique o patch ou instale a atualização.')
if __name__=='__main__':
    try:main()
    except Exception as e:print('ERRO:',e);raise SystemExit(1)
